try:
 import selfies
 s='[C][C][O][C][=Branch1][C][=O][C][=C][C][C][C][Branch1][C][C][N][C][Ring1][#Branch1][=N][C][=C][C][Ring1][=Branch1][=O]'
 smi=selfies.decoder(s)
 print('decoded:',smi)
 try:
  from rdkit import Chem
  m=Chem.MolFromSmiles(smi)
  print('valid:',m is not None)
  print('canonical:',Chem.MolToSmiles(m) if m else None)
 except Exception as e: print('rdkit:',e)
except Exception as e: print(type(e).__name__,e)
